    # Detect a repeated palette strip, either a repeated row or column.
    strip = None
    for r in range(h):
        cols = [c for c, v in enumerate(grid[r]) if v]
        if len(cols) >= 2 and cols == list(range(cols[0], cols[-1] + 1)):
            end = r
            while end + 1 < h and [grid[end + 1][c] for c in cols] == [grid[r][c] for c in cols]:
                end += 1
            if end > r:
                strip = ("row", r, end, cols)
                break

    if strip is None:
        for c in range(w):
            rows = [r for r in range(h) if grid[r][c]]
            if len(rows) >= 2 and rows == list(range(rows[0], rows[-1] + 1)):
                end = c
                while end + 1 < w and [grid[r][end + 1] for r in rows] == [grid[r][c] for r in rows]:
                    end += 1
                if end > c:
                    strip = ("col", c, end, rows)
                    break

    if strip is None:
        return grid

    if strip[0] == "row":
        _, r0, r1, cols = strip
        palette = [grid[r0][c] for c in cols]
        excluded = {(r, c) for r in range(r0, r1 + 1) for c in cols}
    else:
        _, c0, c1, rows = strip
        palette = [grid[r][c0] for r in rows]
        excluded = {(r, c) for r in rows for c in range(c0, c1 + 1)}

    # Extract the silhouette as a connected component, excluding the palette.
    seen = set()
    components = []
    for r in range(h):
        for c in range(w):
            if grid[r][c] == 0 or (r, c) in excluded or (r, c) in seen:
                continue
            color = grid[r][c]
            stack = [(r, c)]
            seen.add((r, c))
            comp = []
            while stack:
                y, x = stack.pop()
                comp.append((y, x))
                for dy, dx in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                    yy, xx = y + dy, x + dx
                    if (0 <= yy < h and 0 <= xx < w and
                        grid[yy][xx] == color and
                        (yy, xx) not in excluded and (yy, xx) not in seen):
                        seen.add((yy, xx))
                        stack.append((yy, xx))
            components.append((comp, color))

    if not components:
        return grid

    comp, template_color = max(components, key=lambda x: len(x[0]))
    min_r = min(r for r, c in comp)
    max_r = max(r for r, c in comp)
    min_c = min(c for r, c in comp)
    max_c = max(c for r, c in comp)
    shape = {(r - min_r, c - min_c) for r, c in comp}
    shape_h = max_r - min_r + 1

    idx = palette.index(template_color) if template_color in palette else 0
    stack_top = min_r - idx * shape_h
    out = [[0] * w for _ in range(h)]

    for i, color in enumerate(palette):
        for dr, dc in shape:
            rr = stack_top + i * shape_h + dr
            cc = min_c + dc
            if 0 <= rr < h and 0 <= cc < w:
                out[rr][cc] = color

    return out
